# frozen_string_literal: true

module PubGrub
  # A package scoped to a single target platform.
  #
  # When solving for multiple target platforms at once (for example
  # +:linux+ and +:macos+), every (package name, platform) pair is fed to the
  # solver as its own package. Packages with the same #name but different
  # platforms are kept in sync by cross-platform incompatibilities generated by
  # MultiPlatformPackageSource.
  class PlatformPackage
    attr_reader :name, :platform

    def initialize(name, platform)
      @name = name
      @platform = platform
    end

    def root?
      false
    end

    def ==(other)
      other.is_a?(PlatformPackage) &&
        other.name == name &&
        other.platform == platform
    end
    alias_method :eql?, :==

    def hash
      [self.class, name, platform].hash
    end

    def <=>(other)
      by_name = name.to_s <=> other.name.to_s
      return by_name unless by_name == 0

      platform.to_s <=> other.platform.to_s
    end

    def to_s
      "#{name} (#{platform})"
    end

    def inspect
      "#<#{self.class} #{name.inspect} on #{platform.inspect}>"
    end

    # The synthetic root package for one target platform. Decisions made for it
    # represent that platform's top-level requirements.
    class Root < PlatformPackage
      def initialize(platform)
        super(:__platform_root__, platform)
      end

      def root?
        true
      end

      def to_s
        "root (#{platform})"
      end
    end
  end
end
